+using System.ComponentModel;
+using System.Text;
+
+namespace ResearchAgent.Tools;
+
+public sealed class NoteTool
+{
+    private readonly List<(string Title, string Content)> _notes = [];
+
+    [Description("Saves a research note with a title and content. Use this to record key findings, facts, or insights discovered during research.")]
+    public string SaveNote(
+        [Description("A short descriptive title for the note")] string title,
+        [Description("The content of the note — facts, insights, or findings")] string content)
+    {
+        _notes.Add((title, content));
+        return $"Note saved: '{title}' (total notes: {_notes.Count})";
+    }
+
+    [Description("Retrieves all saved research notes. Use this to review what has been found so far before writing a summary.")]
+    public string GetAllNotes()
+    {
+        if (_notes.Count == 0)
+        {
+            return "No notes have been saved yet.";
+        }
+
+        var sb = new StringBuilder();
+        sb.AppendLine($"=== Research Notes ({_notes.Count} total) ===\n");
+
+        for (var i = 0; i < _notes.Count; i++)
+        {
+            var (title, content) = _notes[i];
+            sb.AppendLine($"[{i + 1}] {title}");
+            sb.AppendLine($"    {content}");
+            sb.AppendLine();
+        }
+
+        return sb.ToString();
+    }
+}
