using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

public sealed class WebSearchTool
{
    private static readonly HttpClient HttpClient = new();

    [Description("Searches the web for information on a given query and returns relevant results. Use this to find facts, articles, and data about a topic.")]
    public static async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query,
        [Description("Maximum number of results to return (1-5)")] int maxResults = 3)
    {
        maxResults = Math.Clamp(maxResults, 1, 5);

        try
        {
            // Uses DuckDuckGo Instant Answer API (no key required)
            var encodedQuery = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encodedQuery}&format=json&no_html=1&skip_disambig=1";

            var response = await HttpClient.GetStringAsync(url);
            var doc = JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            // Extract abstract if available
            var abstractText = root.GetProperty("Abstract").GetString();
            var abstractSource = root.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.Add($"[{abstractSource}] {abstractText}");
            }

            // Extract related topics
            if (root.TryGetProperty("RelatedTopics", out var relatedTopics))
            {
                foreach (var topic in relatedTopics.EnumerateArray().Take(maxResults))
                {
                    if (topic.TryGetProperty("Text", out var text) &&
                        !string.IsNullOrWhiteSpace(text.GetString()))
                    {
                        var topicText = text.GetString()!;
                        var firstUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : "";
                        results.Add($"- {topicText} ({firstUrl})");
                    }
                }
            }

            if (results.Count == 0)
            {
                return $"No detailed results found for '{query}'. Try rephrasing the query or breaking it into smaller parts.";
            }

            return $"Search results for '{query}':\n\n{string.Join("\n\n", results)}";
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}. Try again with a different query.";
        }
    }
}

