using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using ResearchAgent.Tools;

var configuration = new ConfigurationBuilder()
    .AddEnvironmentVariables()
    .Build();

var apiKey = configuration["OPENAI_API_KEY"]
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var modelId = configuration["OPENAI_MODEL"] ?? "gpt-4o-mini-2024-07-18";

var services = new ServiceCollection();
services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

services.AddChatClient(builder => builder
    .UseLogging()
    .UseFunctionInvocation()
    .Use(new OpenAI.OpenAIClient(apiKey).AsChatClient(modelId)));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();

// Set up tools
var noteTool = new NoteTool();
var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearchTool.SearchWebAsync),
    AIFunctionFactory.Create(noteTool.SaveNote),
    AIFunctionFactory.Create(noteTool.GetAllNotes),
};

var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = tools,
};

// Get research topic from user
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent              ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

string topic;
if (args.Length > 0)
{
    topic = string.Join(' ', args);
}
else
{
    Console.Write("Enter a topic to research: ");
    topic = Console.ReadLine()?.Trim() ?? "";
}

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var systemPrompt = """
    You are a research agent. Your goal is to thoroughly research a topic using the available tools.

    Follow this process:
    1. Search the web for information about the topic from multiple angles (2-4 searches).
    2. For each useful finding, save a note with a descriptive title and the key facts.
    3. After gathering enough information, retrieve all your notes.
    4. Write a comprehensive summary of your findings.

    Be thorough but concise. Focus on factual information.
    """;

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}"),
};

Console.WriteLine("Agent is researching... (this may take a moment)\n");

var response = await chatClient.GetResponseAsync(messages, chatOptions);

Console.WriteLine("═══════════════ RESEARCH SUMMARY ═══════════════\n");
Console.WriteLine(response.Text);
Console.WriteLine("\n═════════════════════════════════════════════════");
Console.WriteLine($"\nTokens used — Input: {response.Usage?.InputTokenCount ?? 0}, Output: {response.Usage?.OutputTokenCount ?? 0}");

